package writer

import "github.com/PorticoMediaServer/portico/server/internal/store/stmt"

type ipReclaimStatements struct{ owner, source, first, next, remove, save, ack stmt.ID }

func ipReclaimStatementSet(f ipReceiptOwnerKind) (ipReclaimStatements, error) {
	switch f {
	case ipReceiptPolicy:
		return ipReclaimStatements{ipRCPolicyOwner, ipRCPolicySource, ipRCPolicyFirst, ipRCPolicyNext, ipRCPolicyRemove, ipRCPolicySave, ipRCPolicyACK}, nil
	case ipReceiptRefresh:
		return ipReclaimStatements{ipRCRefreshOwner, ipRCRefreshSource, ipRCRefreshFirst, ipRCRefreshNext, ipRCRefreshRemove, ipRCRefreshSave, ipRCRefreshACK}, nil
	case ipReceiptText:
		return ipReclaimStatements{ipRCTextOwner, ipRCTextSource, ipRCTextFirst, ipRCTextNext, ipRCTextRemove, ipRCTextSave, ipRCTextACK}, nil
	case ipReceiptArtwork:
		return ipReclaimStatements{ipRCArtworkOwner, ipRCArtworkSource, ipRCArtworkFirst, ipRCArtworkNext, ipRCArtworkRemove, ipRCArtworkSave, ipRCArtworkACK}, nil
	case ipReceiptPerson:
		return ipReclaimStatements{ipRCPersonOwner, ipRCPersonSource, ipRCPersonFirst, ipRCPersonNext, ipRCPersonRemove, ipRCPersonSave, ipRCPersonACK}, nil
	case ipReceiptBulk:
		return ipReclaimStatements{ipRCBulkOwner, ipRCBulkSource, ipRCBulkFirst, ipRCBulkNext, ipRCBulkRemove, ipRCBulkSave, ipRCBulkACK}, nil
	}
	return ipReclaimStatements{}, ErrInvalid
}

